// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address expectedOwner;

    function setUp() public {
        c = new C();
        Initializer init = new Initializer();
        init.doInit(c);
        expectedOwner = address(init);
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // RULE: for ANY caller, c.owner() returns the stored owner (the initializer),
        // independent of msg.sender.
        vm.prank(actor);
        assertTrue(c.owner() == expectedOwner);
    }
}

contract Initializer {
    address public protocolFeeDestination;

    constructor() {
        protocolFeeDestination = address(this);
    }

    function doInit(C c) external {
        c.initialize(1, 1, "v", address(this));
    }
}
